import type { Metadata } from "next";

import { site } from "@/data/site";

/** Generated by `npm run brand-assets` and served by the app/opengraph-image.jpg file convention. */
const shareImage = {
  url: "/opengraph-image.jpg",
  width: 1200,
  height: 630,
  alt: `${site.name} — ${site.tagline} A fictional contemporary restaurant concept in Bengaluru.`,
};

interface PageMetadataInput {
  /** Page name, combined with the site name via the root title template. */
  title?: string;
  description: string;
  path: string;
}

/**
 * Page metadata with complete Open Graph and Twitter fields. Next.js merges
 * metadata shallowly — a page-level `openGraph` replaces the root one, file-based
 * share image included — so every page restates the shared values here.
 */
export function pageMetadata({ title, description, path }: PageMetadataInput): Metadata {
  const fullTitle = title ? `${title} — ${site.name}` : `${site.name} — ${site.tagline}`;
  return {
    title: title ?? { absolute: fullTitle },
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: site.name,
      locale: "en_IN",
      url: path,
      title: fullTitle,
      description,
      images: [shareImage],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [shareImage],
    },
  };
}
